//	  - rsa-pss-2048-sha256 → rsa-pss-2048-sha512 (same RSA key, different hash)
//
//	retain_key_bytes=false (DEFAULT):
//	  - aes-128-cbc → aes-256-gcm (different key size; must regenerate)
//	  - ecdsa-p256-sha256 → ed25519 (different curve; must regenerate)
//	  - ecdsa-p256 → ml-dsa-65 (different algorithm family; must regenerate)
