// ┌─────────────────┬─────────────────┬────────────────────────┐
// │ Source Provider │ Target Provider │ Recommended Strategy   │
// ├─────────────────┼─────────────────┼────────────────────────┤
// │ Software        │ Software        │ PROVIDER_SWITCH        │
// │ Software        │ HSM             │ EXTRACT_AND_IMPORT     │
// │ HSM (extract)   │ Software        │ EXTRACT_AND_IMPORT     │
// │ HSM (no extract)│ Software        │ REKEY_AND_ARCHIVE      │
// │ HSM             │ HSM (compat)    │ WRAPPED_TRANSFER       │
// │ HSM             │ HSM (incompat)  │ EXTRACT_AND_IMPORT     │
// └─────────────────┴─────────────────┴────────────────────────┘
//
// Example 1: Software to software (FIPS compliance)
//
//	MigrateKeyRequest {
//	  name: "encryption-key"
//	  target_instance_id: "openssl3-fips-default"
//	  strategy: MIGRATION_STRATEGY_PROVIDER_SWITCH
//	}
//
