//
//	MigrateKeyRequest {
//	  name: "signing-key"
//	  target_instance_id: "hsm-prod-slot5"
//	  strategy: MIGRATION_STRATEGY_EXTRACT_AND_IMPORT
//	}
//
// Example 3: HSM to HSM with maximum security
//
//	MigrateKeyRequest {
//	  name: "root-key"
//	  target_instance_id: "hsm-dr-site"
//	  strategy: MIGRATION_STRATEGY_WRAPPED_TRANSFER
//	}
//
// Example 4: Migration with algorithm upgrade
//
//	MigrateKeyRequest {
//	  name: "legacy-key"
//	  target_instance_id: "new-provider"
